(function(){
'use strict';
const D=DATA,E=Art.esc,$=s=>document.querySelector(s),fmt=n=>Math.round(n).toLocaleString('ko-KR');
let stored=Save.read(),game=new Game(stored?.account||Meta.fresh(),stored?.run||null),selected=null,modal=null,codexTab='items',contract='standard',supplyNPC=null,toastTimer,previousFocus=null;
const badge=(r,npc=false)=>`<span class="rare-badge r${r}">${(npc?D.npcRarities:D.rarities)[r]}</span>`;
const btn=(text,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const tag=t=>`<span class="tag" title="${E(Presentation.traitText(t))}">${D.traitBy[t].name}</span>`;
const groupStock=()=>{const m=new Map();for(const st of game.run.inventory){if(!m.has(st.item))m.set(st.item,{...st,count:0});const x=m.get(st.item);x.count++;if(st.expires!==null&&(x.expires===null||st.expires<x.expires)){x.id=st.id;x.expires=st.expires;}}return [...m.values()];};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function sound(kind='sale'){Sound.sync(game.account.settings.muted,game.run?.phase);Sound.play(kind==='rare'?'relic':kind);}
function setModal(value){$('#coach-root').innerHTML='';previousFocus=document.activeElement;modal=value;renderModal();if(value){document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root button, #modal-root input')?.focus(),0);}else{document.body.style.overflow='';previousFocus?.focus?.();}requestAnimationFrame(showCoach);}
function header(){const a=game.account,s=game.run;return `<header class="topbar"><div class="brand">GUILD<span>24</span></div><div class="title-block"><h1>던전 앞 편의점</h1><small>${E(s?.branch||'제7게이트점')} · 가맹등급 ${a.grade}</small></div><nav class="topnav" aria-label="게임 메뉴">${btn('매장','shop','active')}${btn('모험가 수첩','roster')}${btn('본사 · 도감','codex')}${btn('도움말','help')}${btn(a.settings.muted?'소리 꺼짐':'소리 켜짐','sound','','aria-label="소리 켜기 또는 끄기"')}${btn('설정','settings')}</nav></header>`;}
let lastPhase=null;
function headerCompact(){
 const s=game.run;return '<header class="game-header"><b class="brand">GUILD<span>24</span></b><strong>DAY '+(s.phase==='foundation'?0:s.day)+'</strong><span class="header-money">'+fmt(s.money)+'G</span>'+btn('메뉴','menu','secondary','aria-label="게임 메뉴"')+'</header>';
}
function render(){
 const s=game.run;Sound.sync(game.account.settings.muted,s?.phase);
 if(!s){$('#app').innerHTML='<div class="layout">'+header()+'<div class="start-background"><h2>오늘도 문을 연다.</h2><p>초기 자금 1,200G · 창고 24칸 · 30일 영업</p>'+(Save.error?'<p class="save-alert">'+E(Save.error)+'</p>':'')+btn('첫 영업 준비','new','primary')+'</div></div>';if(!modal)setModal('new');return;}
 const phase=s.phase,phases=['morning','order','sell','night','closing'],labels=['아침','발주','영업','밤','마감'],idx=phases.indexOf(phase),previousScroll=$('.screen-body')?.scrollTop||0;
 let content=phase==='morning'?morningScreen():phase==='order'?orders():phase==='sell'?saleScreen():phase==='night'?nightScreen():phase==='closing'?closingScreen():phase==='final'?finalSelection():phase==='end'?endBanner()+s.results.map(resultCard).join(''):'<p>첫 점포지원을 고르면 영업이 시작됩니다.</p>';
 const strip='<ol class="phase-strip" aria-label="영업 단계">'+phases.map((p,i)=>'<li class="'+(p===phase?'current':i<idx?'done':'')+'" '+(p===phase?'aria-current="step"':'')+'><span>'+(i+1)+'</span>'+labels[i]+'</li>').join('')+'</ol>';
 $('#app').innerHTML='<div class="game-shell phase-'+phase+'">'+headerCompact()+strip+(phase==='order'?orderBudget():'')+'<main class="screen-body" id="phase-content" tabindex="-1" aria-label="'+(labels[idx]||'최종 영업')+'">'+content+'</main><div class="phase-action">'+phaseAction()+'</div></div>';
 const viewKey=phase+':'+(phase==='sell'?s.cursor:phase==='night'?s.nightCursor:'');const changed=lastPhase!==viewKey;lastPhase=viewKey;$('.screen-body').scrollTop=changed?0:previousScroll;if(changed)$('#phase-content').focus({preventScroll:true});
 if(phase==='foundation')modal='relics';renderModal();requestAnimationFrame(showCoach);
}
function phaseAction(){
 const s=game.run;
 if(s.phase==='morning')return btn('발주로 이동','begin-order','primary');
 if(s.phase==='order')return '<span>선택 '+fmt(game.cartTotal())+'G · 발주 후 '+fmt(s.money-game.cartTotal())+'G</span>'+btn(game.cartTotal()?'발주 확정 · 영업 시작':'추가 발주 없이 영업 시작','finish-order','primary');
 if(s.phase==='sell')return '<span>손님 '+(s.cursor+1)+' / '+s.queue.length+'</span>'+btn(s.cursor+1===s.queue.length?'영업 종료 · 밤 결과':'손님 보내기','depart','primary');
 if(s.phase==='night')return btn('전체 건너뛰기','closing','secondary')+btn(s.nightCursor+1>=s.results.length?'정산으로 이동':'다음 결과','night-next','primary');
 if(s.phase==='closing')return btn('다음 날','close','primary');
 if(s.phase==='final')return btn('점포지원','relics','secondary')+btn('마왕성으로 출발','boss','primary',s.team.length?'':'disabled');
 if(s.phase==='end')return btn('다음 점포 열기','new','primary');
 return '';
}
function gateSummary(){return '<div class="gate-summary">'+game.run.dungeons.map(d=>'<div><b>'+E(d.name)+'</b><span>'+d.hazards.map(h=>D.hazards[h]).join(' · ')+'</span><small>'+(d.requiredSupply?'보급 부담 · 필요 보급 '+d.requiredSupply:'보급 부담 없음')+'</small></div>').join('')+'</div>';}
function nextForecast(){
 const day=game.run.day+1;if(day>=30)return '<div class="next-forecast"><b>내일 예보</b><span>'+(day===30?'마왕성 최종 원정':'이번 영업의 마지막 날')+'</span></div>';
 return '<div class="next-forecast"><b>내일 Tier 예보</b><span>'+Dungeon.tierWeights(day).map((w,i)=>'T'+(i+1)+' '+(Math.round(w*1000)/10)+'%').join(' · ')+'</span><small>종류·손님은 미정</small></div>';
}
function specialUI(){const s=game.run,e=s.special;if(!e||e.used)return '';if(e.kind==='route'){const n=game.current();if(s.phase!=='sell'||!n||n.pack.length||n.history.some(h=>h.day===s.day)||s.dungeons.length<2)return '';return '<details class="special-event"><summary>길드 원정 배치조정 · 오늘 한 번</summary><p>아직 거래하지 않은 '+E(n.name)+'의 목적지를 바꿀 수 있습니다.</p>'+s.dungeons.map((d,i)=>btn(E(d.name),'special','','data-id="'+n.id+'" data-value="'+i+'"')).join('')+'</details>';}if(!['morning','order'].includes(s.phase))return '';const candidates=s.npcs.filter(n=>n.alive&&n.introduced);return '<details class="special-event"><summary>'+(e.kind==='remove'?'길드 상담 · 약점 하나 제거':'길드 특별 훈련 · 이점 하나 배우기')+'</summary>'+candidates.map(n=>{const choices=e.kind==='remove'?n.traits.filter(t=>D.traitBy[t].direction==='negative'):e.candidates.filter(t=>!n.traits.includes(t)&&n.traits.length<Math.min(4,n.traitSlots)&&!D.traitExclusions.some(pair=>pair.includes(t)&&pair.some(id=>n.traits.includes(id))));return choices.length?'<div><b>'+E(n.name)+'</b>'+choices.map(t=>btn(D.traitBy[t].name+' · '+Presentation.traitText(t),'special','','data-id="'+n.id+'" data-value="'+t+'"')).join('')+'</div>':'';}).join('')+'<p>원하지 않으면 선택하지 않아도 됩니다. 오늘 영업 준비가 끝나면 기회가 지나갑니다.</p></details>';}
function morningScreen(){
 const s=game.run;return '<section class="morning-screen"><h1>문 열기 전</h1><div class="morning-scene">'+Art.scene(game)+'</div><div class="today-count" id="visitor-count"><span>오늘 방문 예정 <strong>'+s.queue.length+'명</strong></span><span>열린 게이트 <strong>'+s.dungeons.length+'곳</strong></span></div>'+gateSummary()+specialUI()+(s.event?'<aside class="event-line"><b>'+E(s.event.name)+'</b><p>'+E(s.event.description)+'</p></aside>':'')+'<div class="support-link">'+btn('점포지원 '+s.facilities.length+'/7','relics','secondary')+'<span>보유 '+fmt(s.money)+'G</span></div></section>';
}
function orderBudget(){
 const s=game.run,total=game.cartTotal();return '<div class="order-budget" aria-label="발주 자금"><div><span>보유</span><strong>'+fmt(s.money)+'G</strong></div><div><span>선택 발주</span><strong>'+fmt(total)+'G</strong></div><div><span>발주 후</span><strong>'+fmt(s.money-total)+'G</strong></div></div>';
}
function forecast(n,extra=null){
 const d=game.run.dungeons[n.claimedDestination??n.destination]||game.run.dungeons[0],v={...n,traits:Presentation.traits(n),pack:extra?[...n.pack,extra]:n.pack},p=Dungeon.prepare(v,d,game.run.facilities);
 return '<div class="expedition-forecast"><div><span>전투 전망</span><b>'+Dungeon.estimate(v,d,game.run.facilities)+'</b></div><div class="hazard-readiness">'+p.hazards.map(h=>'<span>'+D.hazards[h.key]+' <b>'+h.label+'</b></span>').join('')+'</div><small>'+(d.requiredSupply?'필요 보급 '+d.requiredSupply+' · 준비 보급 '+Math.round(p.supply.actual):'보급 부담 없음')+' · 부상 '+n.injury+' · 누적 피로 '+n.fatigue+'</small></div>';
}
function returningSummary(n){const r=Presentation.returning(n);if(!r)return '';return '<aside class="returning-summary" aria-label="지난 방문 이후"><b>지난 원정 · DAY '+r.day+' '+E(r.outcome)+'</b>'+(r.changes.length?'<p>'+r.changes.map(E).join(' · ')+'</p>':'')+(r.impact?'<p>'+E(r.impact)+'</p>':'')+'</aside>';}
function saleScreen(){
 const s=game.run,n=game.current();if(!n)return '<p>영업을 마치는 중입니다.</p>';
 return '<section class="sale-screen"><div class="counter-scene">'+Art.scene(game)+'</div><button class="customer-identity" data-action="npc" data-id="'+n.id+'">'+Art.avatar(n,64)+'<span><strong>'+E(n.name)+'</strong><span>Lv.'+n.level+' '+D.jobBy[n.job].name+' · '+n.status+'</span><span>소지금 '+fmt(n.money)+'G · 단골도 '+n.loyalty+'</span></span><span class="detail-hint">기록 ›</span></button>'+returningSummary(n)+'<div class="sale-context"><div>'+destination(n)+statGrid(n)+'</div><div>'+traitRows(n)+forecast(n)+'</div></div><div class="bag-line">보급 '+n.pack.length+'/'+Adventurer.slots(n)+' · '+(n.pack.map(id=>D.itemBy[id].name).join(', ')||'빈 가방')+'</div>'+specialUI()+inventory()+'</section>';
}
function nightScreen(){
 const s=game.run,r=s.results[s.nightCursor||0];return '<section class="night-screen"><h1>밤의 귀환 <small>'+Math.min((s.nightCursor||0)+1,s.results.length)+' / '+s.results.length+'</small></h1>'+(r?resultCard(r):'<p>오늘은 원정에 나선 손님이 없었다.</p>')+'</section>';
}
function closingScreen(){
 const s=game.run,d=s.daily,margin=d.revenue-d.cogs,profit=margin+(d.subsidy||0)+(d.commission||0)-d.operating-(d.wasteCost||0)-(d.rerollSpent||0);
 const row=(label,value)=>'<div><span>'+label+'</span><b>'+fmt(value||0)+'G</b></div>';
 return '<section class="closing-screen"><p class="eyebrow">GUILD24 · DAY '+s.day+'</p><h1>오늘의 마감</h1><div class="closing-receipt">'+row('매출',d.revenue)+row('판매된 상품 원가 (COGS)',-d.cogs)+row('판매 마진',margin)+row('운영비',-d.operating)+row('폐기 원가',-d.wasteCost)+row('발주 교환 비용',-d.rerollSpent)+row('본사 지원·수당',(d.subsidy||0)+(d.commission||0))+'<div class="receipt-total"><span>영업 손익</span><b>'+fmt(profit)+'G</b></div>'+row('오늘 발주 지출',-d.spent)+row('점포지원 투자',-d.relicSpent)+row('재고 정리 회수',d.liquidation)+'<div class="receipt-total final-gold"><span>보유 자금</span><b>'+fmt(s.money)+'G</b></div></div><p class="smalltext">미판매 재고는 자산으로 남습니다. 발주 지출과 판매 원가를 손익에서 중복 차감하지 않습니다.</p><details><summary>가격 선택과 보급 기록</summary><p>바가지 추가 매출 '+fmt(d.overcharge)+'G · 반값으로 포기한 매출 '+fmt(d.discount)+'G</p>'+s.results.filter(r=>r.events?.length).map(r=>'<p><b>'+E(r.name)+'</b> · '+E(r.events[0].text)+'</p>').join('')+'</details>'+(s.money<0?'<p>운영비가 부족합니다.</p>'+btn('재고 정리','stock')+btn('폐점','retire','danger'):'')+'</section>';
}
const coachSteps={
 morning:[['visitors','#visitor-count','오늘 방문할 인원입니다. 시설·계약·이벤트에 따라 달라집니다.'],['gates','.gate-summary','열린 게이트의 위험을 보고 준비할 상품을 생각해 보세요.']],
 order:[['gold','.order-budget','수량을 고르는 동안 보유 자금과 발주 후 자금이 여기 남아 있습니다.'],['quantity','.order-controls','수량을 골라 주세요. 같은 상품을 여러 개 발주할 수 있습니다.'],['reroll','.reroll-button','발주 후보 전체를 교환합니다. 같은 날 반복할수록 비용이 올라갑니다.'],['confirm','.phase-action .primary','발주를 확정하면 현재 재고로 영업을 시작합니다.']],
 sell:[['npc','.customer-identity','손님을 눌러 특성과 원정 기록을 살펴보세요.','npc'],['destination','.destination','이 손님이 향할 게이트입니다. 허세가 있다면 말한 목적지가 다를 수 있습니다.'],['forecast','.expedition-forecast','원정 전망은 현재 능력과 준비를 바탕으로 한 예상입니다. 실제 결과는 예상과 달라질 수 있습니다.'],['inventory','.sale-product','진열 상품 전체에서 고릅니다. 판매한 소비품은 오늘 원정에서 사용됩니다.']],
 saleItem:[['pricing','.price-actions','반값은 손님에게 투자, 정가는 기본 거래, 바가지는 지금의 수입을 늘리는 선택입니다.']],
 night:[['result','.result-card .identity','한 명씩 결과와 원인, 성장을 확인합니다. 전체 건너뛰기로 정산에 갈 수도 있습니다.']],
 closing:[['receipt','.closing-receipt','판매 마진에서 운영비와 폐기를 뺀 영업 손익입니다. 발주와 점포지원 투자는 아래에 따로 표시됩니다.']]
};
let activeCoach=null;
function showCoach(){
 const root=$('#coach-root');if(!root)return;root.innerHTML='';activeCoach=null;
 const tutorial=game.account.tutorial||{};if(tutorial.skipped||modal&&modal!=='saleItem')return;
 const steps=coachSteps[modal==='saleItem'?'saleItem':game.run?.phase]||[],step=steps.find(x=>!tutorial['coach-'+x[0]]);if(!step)return;
 const target=$(step[1]);if(!target||!target.getClientRects().length)return;
 const view=target.getBoundingClientRect();if(view.top<80||view.bottom>innerHeight-100){target.scrollIntoView({block:'center',behavior:'instant'});}
 const b=target.getBoundingClientRect(),left=Math.max(4,b.left-4),top=Math.max(4,b.top-4),width=Math.min(innerWidth-left-4,b.width+8),height=Math.min(b.height+8,180),bottom=top+height;
 const bw=Math.min(340,innerWidth-24),bh=210,x=Math.max(12,Math.min(innerWidth-bw-12,left)),y=bottom+bh+12<innerHeight?bottom+12:Math.max(12,top-bh-12);
 const block=(l,t,w,h)=>'<div class="coach-block" style="left:'+l+'px;top:'+t+'px;width:'+Math.max(0,w)+'px;height:'+Math.max(0,h)+'px"></div>';
 root.innerHTML='<div class="coach-layer">'+block(0,0,innerWidth,top)+block(0,bottom,innerWidth,innerHeight-bottom)+block(0,top,left,height)+block(left+width,top,innerWidth-left-width,height)+'<div class="coach-focus" style="left:'+left+'px;top:'+top+'px;width:'+width+'px;height:'+height+'px"></div><section class="coach-bubble" role="dialog" aria-label="점주 안내" style="left:'+x+'px;top:'+y+'px;width:'+bw+'px"><small>점주 안내</small><p>'+step[2]+'</p><div>'+btn('안내 건너뛰기','coach-skip','coach-skip')+btn(step[3]?'눌러서 살펴보기':'다음','coach-next','primary')+'</div></section></div>';
 activeCoach=step;
}
function finishCoach(skip=false){
 if(!activeCoach&&!skip)return;game.account.tutorial??={};if(skip)game.account.tutorial.skipped=true;else game.account.tutorial['coach-'+activeCoach[0]]=true;game.save();$('#coach-root').innerHTML='';activeCoach=null;requestAnimationFrame(showCoach);
}
window.addEventListener('resize',()=>{if(activeCoach)showCoach();});
function effectList(it,compact=false){const rows=Presentation.rows(it.effects);const html=r=>`<li class="${r.bad?'effect-bad':''}"><span>${E(r.label)}</span><b>${r.text}</b></li>`;return `<ul class="effects">${rows.slice(0,compact?4:rows.length).map(html).join('')}</ul>${compact&&rows.length>4?`<details><summary>전체 효과</summary><ul class="effects">${rows.slice(4).map(html).join('')}</ul></details>`:''}`;}
function traitRows(n){return `<div class="trait-list">${Presentation.traits(n).map(t=>`<div class="trait-row ${D.traitBy[t].direction}"><b><small>${D.traitDirections[D.traitBy[t].direction]}</small> ${D.traitBy[t].name}</b><span>${E(Presentation.traitText(t))}</span></div>`).join('')}${n.traits.length>Presentation.traits(n).length?'<p class="muted">미발견 특성 · 더 알아가는 중</p>':''}</div>`;}
function destination(n){const d=game.run.dungeons[n.claimedDestination??n.destination];if(!d)return '';const known=Presentation.known(d,game);return `<div class="destination"><span>${n.traits.includes('showoff')&&Presentation.traits(n).includes('showoff')?'말한 목적지':'목적지'}</span><h3>${E(d.name)}</h3><p>${known.map(h=>D.hazards[h]).join(' · ')||'위험 미확인'}${known.length<d.hazards.length?' · 미확인 위험 있음':''}</p></div>`;}
function statGrid(n){const values=Dungeon.prepare({...n,traits:Presentation.traits(n)},game.run.dungeons[n.claimedDestination??n.destination]||game.run.dungeons[0],game.run.facilities).effects;return `<div class="detail-stats">${Adventurer.keys.map(k=>`<div class="detail-stat"><label>${Presentation.labels[k]}</label><strong>${Math.round(values[k])}</strong></div>`).join('')}</div><p class="smalltext">공개 특성·장비·현재 보급 반영</p><div class="resistances">${['cold','fire','poison','fear'].map(k=>`<span>${Presentation.labels[k]} <b>${Math.round(values[k]||0)}</b></span>`).join('')}</div>`;}
function orders(){
 const s=game.run;return '<section class="order-screen">'+(s.phase==='final'?orderBudget():'')+'<details class="today-gates"><summary>오늘 '+s.queue.length+'명 · '+s.dungeons.map(d=>d.name+' ('+d.hazards.map(h=>D.hazards[h]).join('·')+')').join(' / ')+'</summary>'+gateSummary()+'</details>'+nextForecast()+'<div class="section-title"><h1>본사 발주</h1>'+btn('재고 '+s.inventory.length+'/'+game.capacity(),'stock','secondary')+btn('점포지원','relics','secondary')+'</div><div class="order-list">'+s.offers.map((o,i)=>{
 const it=D.itemBy[o.item],q=s.cart?.[i]||0,max=game.maxQuantity(i);return '<article class="order-product r'+it.rarity+'"><div class="product-heading">'+Art.itemIcon(it.id,40)+'<div><h2>'+it.name+'</h2><span>'+D.categories[it.category]+' · '+it.roles.map(r=>D.roles[r]).join(' / ')+'</span></div>'+badge(it.rarity)+'</div><div class="product-body"><div>'+effectList(it,true)+'<p class="product-prices">매입 <b>'+o.price+'G</b> · 정가 <b>'+it.sell+'G</b></p><p class="smalltext">기본 이익 '+(it.sell-o.price)+'G · 재고 '+s.inventory.filter(st=>st.item===it.id).length+' · 공급 '+o.quantity+'</p></div><div class="order-controls"><div class="quantity">'+btn('−','qty','', 'data-index="'+i+'" data-q="'+Math.max(0,q-1)+'" aria-label="'+it.name+' 수량 줄이기" '+(q?'':'disabled'))+'<output aria-label="'+it.name+' 발주 수량">'+q+'</output>'+btn('+','qty','','data-index="'+i+'" data-q="'+(q+1)+'" aria-label="'+it.name+' 수량 늘리기" '+(q>=max?'disabled':''))+'</div><div class="quick">'+[1,3].map(v=>btn(v,'qty','','data-index="'+i+'" data-q="'+v+'" '+(v>max?'disabled':''))).join('')+btn('최대','qty','','data-index="'+i+'" data-q="'+max+'"')+'</div></div></div></article>';
 }).join('')+'</div>'+btn('발주 전체 리롤 '+fmt(game.rerollPrice())+'G','reroll','reroll-button',game.rerollPrice()>s.money||game.cartTotal()?'disabled':'')+(s.phase==='final'?btn('발주 확정','confirm-order','primary',game.cartTotal()?'':'disabled'):'')+'</section>';
}
function inventory(isFinal=false){
 const s=game.run,stocks=groupStock();return '<section class="sale-inventory"><h2>'+(isFinal?'대원에게 보급':'진열 상품')+'</h2><p class="smalltext">상품을 누르면 변화와 세 가격을 비교합니다.</p><div class="sale-products">'+stocks.map(st=>{const it=D.itemBy[st.item];return '<button class="sale-product r'+it.rarity+'" data-action="select" data-id="'+st.id+'">'+Art.itemIcon(it.id,38)+'<span><b>'+it.name+'</b><span>'+Presentation.rows(it.effects).slice(0,2).map(r=>r.label+' '+r.text).join(' · ')+'</span></span><span class="sale-stock"><b>'+it.sell+'G</b><span>재고 '+st.count+'</span></span></button>';}).join('')+'</div>'+(!stocks.length?'<p>진열대가 비었다.</p>':'')+'</section>';
}
function saleItem(){
 const s=game.run,st=s.inventory.find(x=>x.id===selected),n=s.phase==='final'?s.npcs.find(n=>n.id===supplyNPC):game.current();if(!st||!n)return '<p>상품과 손님을 선택해 주세요.</p>';const it=D.itemBy[st.item],isFinal=s.phase==='final';
 const priceButtons=isFinal?btn('대원에게 보급','supply','primary',n.pack.length>=Adventurer.slots(n)?'disabled':''):['half','full','overcharge'].map(mode=>{const p=game.interest(n,it,mode);return btn(D.pricing[mode].label+'<strong>'+p.price+'G</strong><small>이익 '+(p.price-st.cost)+'G</small><small>부담 '+p.burden+'</small>','sell',mode==='full'?'primary':'','data-mode="'+mode+'" '+(p.debit>n.money||n.refused.includes(it.id+':'+mode)||n.pack.length>=Adventurer.slots(n)?'disabled':''));}).join('');
 return '<div class="sale-item-detail"><div class="product-heading">'+Art.itemIcon(it.id,46)+'<div><h2>'+it.name+'</h2><p>'+E(n.name)+' · 소지금 '+fmt(n.money)+'G</p></div></div><p>'+D.categories[it.category]+' · '+it.roles.map(r=>D.roles[r]).join(' / ')+'</p><h3>보급 후 변화</h3><ul class="effects">'+Presentation.preview(n,s.dungeons[n.claimedDestination??n.destination]||s.dungeons[0],s.facilities,it.id).map(r=>'<li class="'+(r.bad?'effect-bad':'')+'"><span>'+r.label+'</span><b>'+Presentation.amount(r.key,r.before)+' → '+Presentation.amount(r.key,r.after)+'</b></li>').join('')+'</ul>'+forecast(n,it.id)+'<details><summary>전체 효과 · 상품 설명</summary>'+effectList(it)+'<p>'+E(it.description)+'</p></details><p class="smalltext">'+(st.expires===null?'유통기한 없음':'폐기까지 '+(st.expires-s.day)+'일')+' · 가장 먼저 폐기될 재고부터 판매</p><div class="price-actions">'+priceButtons+'</div></div>';
}
function outcomeReason(r){if(r.outcome==='사망')return '전투에서 밀린 뒤 돌아오지 못했다.';if(r.avoidedDeath)return '보급이 마지막 순간의 사망을 막았다.';if(r.outcome==='중상')return '큰 부상을 입었다. 회복할 시간이 필요하다.';if(r.outcome==='퇴각')return '원정은 끝내지 못했지만 무사히 빠져나왔다.';if(r.outcome==='부상')return (r.combatWon??r.debug?.combatSuccess)?'전투를 이겼지만 돌아오는 길은 험했다.':'원정을 끝내지 못하고 다친 채 돌아왔다.';return r.outcome==='대성공'?'예상보다 일찍 게이트에서 나왔다.':'원정을 마치고 돌아왔다.';}
function relicMenu(){const s=game.run,w=s.relicWindow;if(!w)return '<p>다음 점포지원은 다음 5일 단위 영업일에 도착합니다.</p>';return `<p>${w.milestoneDay===0?'첫 지원은 무료입니다. 하나를 골라 영업을 시작하세요.':`DAY ${w.milestoneDay} 지원 · ${w.expiryDay===31?'마왕성 출발 전까지':`DAY ${w.expiryDay-1}까지`} 구매 가능 · 자금 ${fmt(s.money)}G`}</p>${w.purchased?`<p class="discovery">구매 완료 · ${D.relicBy[w.purchased].name}</p>`:''}<div class="upgrade-grid">${w.candidateIds.map((id,i)=>{const r=D.relicBy[id],price=w.candidatePrices[i];return `<article class="relic-card"><small>${r.tags.map(t=>D.buildNames[t]).join(' + ')||'운영 보조'} · ${{foundation:'기반',hybrid:'복합',keystone:'핵심',utility:'보조'}[r.kind]}</small><h3>${r.name}</h3><p>${r.description}</p><strong>${price?fmt(price)+'G':'무료'}</strong>${btn(w.purchased===id?'설치됨':'선택 · 구매','buy-relic','primary',`data-id="${id}" ${!game.canBuyRelic()||s.money<price?'disabled':''}`)}</article>`;}).join('')}</div>${w.milestoneDay>0&&!w.purchased?'<p>보류해도 후보와 가격은 유지됩니다. 구매하지 않은 지원은 이후에 다시 등장할 수 있습니다.</p>':''}`;}
function resultCard(r){const n=game.run.npcs.find(n=>n.id===r.npcId);return `<article class="result-card ${r.outcome==='사망'?'dead':['중상','부상'].includes(r.outcome)?'injured':''}"><div class="identity">${Art.avatar(n,56)}<div><span class="outcome">${r.outcome==='사망'?'■ 영구 사망':r.outcome==='중상'?'▰ 중상 · 휴식 필요':r.rescued?'◇ 위기에서 귀환':r.outcome}</span><h3>${E(r.name)}</h3><small>${E(r.dungeonName)} · Lv.${r.level}</small></div></div>${r.routeChange?`<p class="route-change">${E(r.routeChange)}</p>`:''}<p>${E(outcomeReason(r))}</p><p>${r.combatWon===false?'적을 물리치지 못했다.':r.combatWon===true?'적을 물리쳤다.':''}${r.environmentHurt?(r.cause&&r.cause!=='accident'?' '+(D.hazards[r.cause]||'보급 부담')+' 때문에 원정 중 고전했다.':' 원정 중 예상치 못한 사고가 있었다.'):''}</p>${r.recovery?`<p>휴식 ${r.recovery}일</p>`:r.injury?`<p>남은 부상 · 강인함 -${r.injury*5}, 전투 -${r.injury*3}</p>`:''}<div class="result-influence">${(r.events||[]).slice(0,2).map(e=>`<p>${E(e.text)}</p>`).join('')}</div><ul>${r.changes.slice(0,3).map(c=>`<li>${E(c)}</li>`).join('')}</ul>${(r.statChanges||[]).slice(0,4).map(x=>`<p>${Presentation.labels[x.key]} ${Math.round(x.before)} → ${Math.round(x.after)}</p>`).join('')}<p>경험치 +${r.xp} · 전리품 ${r.loot}G</p><blockquote>${E(r.quote)}</blockquote></article>`;}
function endBanner(){const s=game.run,a=game.account;return `<div class="end-banner"><div class="eyebrow">${s.win?'THE GATE IS CLOSED':'END OF THIS RUN'}</div><h2>${s.win?'우리가 키운 애들이, 해냈다.':'이번 점포의 영업이 끝났습니다.'}</h2><p>${E(s.endReason)}</p><div class="row wrap" style="margin-top:15px"><span class="meta-xp">점주 XP +${s.metaReward||0}</span><span class="muted">가맹등급 ${a.grade} · 누적 ${a.xp} XP · ${a.runs}번째 런</span>${btn('해금 확인','codex','small')}</div></div>`;}
function npcCard(n,action='npc'){const s=game.run;return `<button class="npc-card r${n.rarity} ${!n.alive?'dead':''} ${s.team.includes(n.id)?'chosen':''}" data-action="${action}" data-id="${n.id}" ${action==='team'&&(!n.alive||n.recovery)?'disabled':''}><div class="row">${Art.avatar(n,56)}<div>${badge(n.rarity,true)}<h3 style="margin-top:5px">${E(n.name)}</h3><p>Lv.${n.level} ${Adventurer.rank(n)}</p><p>${n.status}${n.recovery?' · '+n.recovery+'일 휴식':''} · 방문 ${n.visits}회</p></div></div><div class="loyalty"><div class="row between"><span>단골도 ${n.loyalty}</span><span>${action==='team'?(s.team.includes(n.id)?'선택됨':'원정대 선택'):'기록 보기'}</span></div><div class="bar"><span style="width:${n.loyalty}%"></span></div></div></button>`;}
function finalSelection(){const s=game.run;if(!s.team.includes(supplyNPC))supplyNPC=s.team[0]||null;return `<section class="inventory-section"><div class="section-title"><h2>최종 원정대 <span class="sub">${s.team.length}/3명 선택 · 중상 회복 중인 모험가는 출전 불가</span></h2></div><details class="final-order"><summary>마지막 발주 · 아이템과 점포지원 사이의 선택</summary>${orders()}</details><div class="npc-grid">${s.npcs.filter(n=>n.alive&&n.introduced).sort((a,b)=>b.level-a.level).map(n=>npcCard(n,'team')).join('')}</div><div class="final-team">${s.team.map(id=>{const n=s.npcs.find(n=>n.id===id);return `<button class="final-member ${supplyNPC===id?'active':''}" data-action="supply-target" data-id="${id}"><b>${E(n.name)}</b><div class="pack">${Array.from({length:Adventurer.slots(n)},(_,i)=>`<div class="slot ${n.pack[i]?'filled':''}">${n.pack[i]?Art.itemIcon(n.pack[i],32):'빈 슬롯'}</div>`).join('')}</div></button>`;}).join('')}</div>${inventory(true)}${!s.npcs.some(n=>n.alive&&!n.recovery)?btn('출전 불가 · 런 종료','retire','danger'):''}</section>`;}
function roster(){const s=game.run;if(!s)return '<p>첫 영업을 시작하면 모험가 수첩이 열립니다.</p>';return `<p class="muted" style="margin-bottom:16px">이름을 누르면 마지막 보급과 원정 기록을 확인할 수 있습니다. 사망한 모험가의 기록도 남습니다.</p><div class="npc-grid">${s.npcs.filter(n=>n.introduced).sort((a,b)=>Number(b.alive)-Number(a.alive)||b.loyalty-a.loyalty).map(n=>npcCard(n)).join('')}</div>`;}
function npcDetail(id){const n=game.run.npcs.find(n=>n.id===id);if(!n)return '';return `<div class="npc-detail"><div class="identity">${Art.avatar(n,92)}<div>${badge(n.rarity,true)}<h2>${E(n.name)} · Lv.${n.level}</h2><p>${Adventurer.rank(n)} · ${n.status}</p><p>단골도 ${n.loyalty} · 방문 ${n.visits}회</p></div></div>${game.run.phase==='sell'&&game.current()?.id===n.id?destination(n):''}${statGrid(n)}${traitRows(n)}<p>${E(n.equipment.name)} · 전투 +${n.equipment.power}</p><p>남은 부상 ${n.injury} · 피로 ${n.fatigue} · 휴식 ${n.recovery}일</p><p class="muted">${n.loyalty>=51?'성장 잠재력: '+(n.potential>=1.18?'빠른 성장':n.potential>=1.1?'꾸준한 성장':'착실한 성장'):'더 친해지면 성장 잠재력과 남은 특성을 알 수 있습니다.'}</p><h3>원정 기록</h3>${n.records.slice().reverse().map(r=>`<div class="history-row"><b>DAY ${r.day} · ${E(r.dungeonName)} · ${r.outcome}</b><p>${r.items.map(i=>D.itemBy[i].name).join(' + ')||'보급 없음'}</p>${r.routeChange?`<p>${E(r.routeChange)}</p>`:''}</div>`).join('')||'<p>아직 원정 기록이 없다.</p>'}<h3>구매 영수증</h3>${n.history.slice(-12).reverse().map(h=>`<div class="history-row">DAY ${h.day} · ${D.itemBy[h.item].name} · ${Presentation.modeLabel(h.mode)} ${fmt(h.paid)}G</div>`).join('')}</div>`;}
function unlockProgress(key){if(!key)return '기본 제공';const [label,target]=D.unlocks[key];const val=game.account.progress[key]||0;return game.account.unlocked.includes(key)?'해금 완료':`${label} ${Math.min(val,target)}/${target}`;}
function codex(){const a=game.account;let list=codexTab==='items'?D.items:codexTab==='jobs'?D.jobs:codexTab==='facilities'?D.relics:codexTab==='contracts'?D.contracts:[];return `<div class="row between wrap" style="margin-bottom:18px"><div><h3>본사 가맹등급 ${a.grade} · ${fmt(a.xp)} XP</h3><p class="smalltext">${['','신입 점주','초기자금 +50G','일반 상품 +1 추가','기본 창고 +2 추가','리롤 비용 감소 추가','첫 던전 정보 +1 추가'][a.grade]} · 이전 등급 혜택 누적</p></div><span class="muted">${a.runs}회 영업 · ${a.wins}회 마왕 토벌</span></div><details><summary>발견 수첩 · ${(a.discoveries||[]).length}개</summary>${(a.discoveries||[]).map(e=>`<p class="discovery">${E(e.text)}</p>`).join('')||'<p>아직 기록된 발견이 없다.</p>'}</details><div class="tabs">${[['items','상품 '+D.items.length],['jobs','직업 6'],['facilities','점포지원 '+D.relics.length],['monsters','몬스터 지식'],['contracts','시작 계약']].map(([id,label])=>btn(label,'codex-tab',codexTab===id?'small active':'small',`data-id="${id}"`)).join('')}</div><div class="unlock-grid">${codexTab==='monsters'?D.dungeons.map(d=>{const seen=a.knowledge[d.id]||0;return `<div class="unlock ${seen?'':'locked'}"><h3>${seen?d.monster:'???'}</h3><p>${d.name} · 관찰 ${seen}회</p><p>${seen?d.hazards.slice(0,seen>=3?3:1).map(h=>D.hazards[h]).join(' · '):'위험 특성 ???'}</p><p>${seen>=5?'약점: '+d.weakness:'약점 ???'}</p></div>`;}).join(''):list.map(it=>`<div class="unlock ${it.unlock&&!a.unlocked.includes(it.unlock)?'locked':''}">${codexTab==='items'?Art.itemIcon(it.id,42):''}<h3>${E(it.name)}</h3><p>${E(it.description||'길드 등록 직업.')}</p>${it.effects?effectList(it):''}<p class="gold-text" style="margin-top:8px">${unlockProgress(it.unlock)}</p></div>`).join('')}</div>`;}
function stockModal(){const s=game.run;return `<p class="muted" style="margin-bottom:15px">유통기한은 입고일부터 계산합니다. 재고 정리는 상품 기본 매입가의 50%를 회수합니다.</p><div class="unlock-grid">${groupStock().map(st=>{const it=D.itemBy[st.item];return `<div class="unlock">${Art.itemIcon(it.id,43)}<h3>${it.name} ×${st.count}</h3><p>${st.expires===null?'유통기한 없음':(st.expires-s.day)+'일 남음'}</p>${['morning','order','night','closing','final'].includes(s.phase)?btn('1개 정리 +'+Math.floor(it.buy*.5)+'G','liquidate','small',`data-id="${st.id}"`):''}</div>`;}).join('')||'<p>창고가 비어 있습니다.</p>'}</div>`;}
function newRun(){return `<div class="eyebrow">길드리테일 가맹 계약</div><h2 class="welcome-title">오늘도 문을 연다.</h2><p class="muted">기본 자금 1,200G · 창고 24칸 · 마왕성 개방까지 30일.</p><div class="welcome-band">계약서를 접어 카운터 아래 넣었다. 시작 재고는 창고에 있다.</div><h3 style="margin-bottom:10px">시작 계약</h3><div class="contract-grid">${D.contracts.map(c=>{const locked=c.unlock&&!game.account.unlocked.includes(c.unlock);return `<button class="contract ${contract===c.id?'active':''}" data-action="contract" data-id="${c.id}" ${locked?'disabled':''}><strong>${c.name}${locked?' · 잠김':''}</strong><span class="muted">${c.description}</span>${locked?'<br><small>'+unlockProgress(c.unlock)+'</small>':''}</button>`;}).join('')}</div><details style="margin-top:15px"><summary class="smalltext">재현용 Seed 지정</summary><label class="smalltext" for="seed">비워 두면 새로운 Seed로 시작합니다.</label><input id="seed" class="seed-field" placeholder="예: guild24-first-shift" maxlength="80"></details>${game.run&&game.run.phase!=='end'?'<p class="danger-text" style="margin-top:14px">진행 중인 점포는 여기서 마감됩니다. 점주 XP를 받고 새로운 런을 시작합니다.</p>':''}`;}
function settings(){return `<div class="stack"><p>자동저장은 현재 브라우저에 보관됩니다. 다른 기기로 옮길 때 저장 파일을 내보내세요.</p><div class="row wrap">${btn('저장 내보내기','export','primary')}${btn('저장 가져오기','import')}</div><div class="row wrap">${btn(game.account.settings.muted?'소리 켜기':'소리 끄기','sound')}</div><hr style="border:0;border-top:1px solid var(--line);width:100%"><p class="muted">게임의 시간은 행동할 때만 흐릅니다. 소리는 처음에 꺼져 있습니다.</p>${game.run&&game.run.phase!=='end'?btn('현재 런 마감 · 새 점포 준비','new','danger'):''}<small>버전 0.4 · 로컬 실행 지원 · 외부 연결 없음</small></div>`;}
function help(){return `<div class="stack"><h3>점포지원</h3><p>DAY 0에는 무료로 하나를 선택합니다. DAY 5·10·15·20·25·30에는 자금을 써서 구매합니다. 사지 않은 후보는 다음 구매 기회 전날까지 보류할 수 있습니다. 판매 중에는 구매할 수 없습니다.</p><h3>발주</h3><p>기본 방문객은 3~6명. 시설·계약·이벤트와 활동 가능한 모험가 수에 따라 달라집니다. 아침에 표시된 인원은 오늘 실제 방문할 인원입니다. 게이트는 초반 1곳에서 후반 최대 3곳까지 열리고, 임시 게이트가 추가될 수 있습니다.</p><p>수량을 고른 뒤 발주를 확정합니다. 남은 재고와 유통기한, 운영비도 확인하세요.</p><h3>판매와 관계</h3><p>목적지·능력·특성을 보고 상품을 고릅니다. 바가지는 수입과 관계를 맞바꾸고, 반값은 이익을 포기해 손님에게 투자합니다. 정가는 기본 거래입니다. 같은 상품·같은 가격으로 거절당한 제안은 그날 반복할 수 없습니다.</p><p>단골도는 구매 의사와 재방문에 영향을 줍니다. 능력을 직접 올리지는 않습니다. 숨겨진 특성은 관계가 쌓이면 공개됩니다.</p><h3>원정과 마감</h3><p>판매한 소비품은 그날 원정에서 사용됩니다. 기본 2칸, Lv.10부터 최대 3칸입니다. 밤에는 귀환 결과를 보고, 마감에서 거래와 보급의 작용을 확인합니다.</p><p>사망은 이번 영업에서 영구적입니다. 중상은 며칠의 휴식이 필요합니다. 30일에는 마지막 발주와 점포지원을 결정하고, 최대 3명에게 보급해 마왕성으로 보냅니다.</p><p>영업이 끝나면 상품 해금·몬스터 지식·발견·가맹등급은 남습니다. 모험가·재고·돈·설비는 다음 영업에 이어지지 않습니다.</p><p>적자일 때는 재고 정리로 운영비를 충당할 수 있습니다. 시간을 재촉하는 제한은 없습니다.</p></div>`;}
function renderModal(){const root=$('#modal-root');if(!modal){root.innerHTML='';document.body.style.overflow='';return;}let title='',body='',footer='',narrow=false;const s=game.run;
 if(modal==='new'){title='새 점포 준비';body=(Save.error?'<p class="save-alert">'+E(Save.error)+'</p>':'')+newRun();footer=btn('첫 점포지원 고르기','start','primary');narrow=true;}
 else if(modal==='relics'){title=s.phase==='foundation'?'DAY 0 · 첫 점포지원':'점포지원';body=relicMenu();}
 else if(modal==='menu'){title='점포 메뉴';body='<div class="menu-list">'+btn('모험가 수첩','roster')+btn('본사 · 도감','codex')+btn('점주 가이드','help')+btn('설정 · 저장','settings')+btn('소리 켜기 / 끄기','sound')+'</div>';narrow=true;}
 else if(modal==='saleItem'){title='상품과 가격';body=saleItem();narrow=true;}
 else if(modal==='roster'){title='모험가 수첩';body=roster();}
 else if(modal.startsWith('npc:')){title='우리 점포의 모험가';body=npcDetail(modal.slice(4));footer=btn('수첩으로','roster');}
 else if(modal==='codex'){title='본사 · 해금 도감';body=codex();}
 else if(modal==='stock'){title='창고 재고';body=stockModal();}
 else if(modal==='help'){title='점주 가이드';body=help();narrow=true;}
 else if(modal==='settings'){title='영업 설정';body=settings();narrow=true;}
 else if(modal==='bossConfirm'){title='제0게이트 — 마지막 출발';body='<p>선택한 원정대가 마왕성으로 출발합니다. 남은 슬롯과 보급을 확인하셨나요?</p>';footer=btn('보급으로 돌아가기','dismiss')+btn('최종 원정 시작','boss-go','gold');narrow=true;}
 else if(modal==='retireConfirm'){title='이번 영업을 마감할까요?';body='<p>현재 런의 자원과 모험가는 다음 런으로 이어지지 않습니다. 지금까지의 활동으로 점주 XP를 받습니다.</p>';footer=btn('계속 영업','dismiss')+btn('폐점 · 보상 받기','retire-go','danger');narrow=true;}
 else if(modal==='importConfirm'){title='저장 파일 가져오기';body='<p>현재 브라우저의 진행을 가져온 저장으로 교체합니다. 기존 진행을 남기려면 먼저 내보내 주세요.</p>';footer=btn('저장 내보내기','export')+btn('파일 선택','import-go','primary');narrow=true;}
 else if(modal==='debug'){title='개발용 Debug · 일반 플레이 비노출';body=`<pre class="debug">${E(JSON.stringify({seed:s.seed,rngState:s.rngState,lastRNG:game.rng.last,offers:s.offers.map(o=>({...o,rarity:D.itemBy[o.item].rarity})),npc:game.current(),dungeons:s.dungeons,results:s.results.map(r=>({name:r.name,outcome:r.outcome,...r.debug})),boss:s.bossDebug},null,2))}</pre>`;}
 root.innerHTML=`<div class="modal-shade"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="modal-header"><h2>${title}</h2>${game.run?.phase!=='foundation'&&(game.run||modal!=='new')?btn('✕','dismiss','icon','aria-label="창 닫기"'):''}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';
}
async function action(el){const a=el.dataset.action,id=el.dataset.id,s=game.run;const oldUnlocks=[...game.account.unlocked];try{
 if(activeCoach&&activeCoach[3]===a)finishCoach();
 switch(a){
 case'coach-skip':finishCoach(true);break;
 case'coach-next':{const actionName=activeCoach?.[3];finishCoach();if(actionName==='npc')setModal('npc:'+game.current().id);break;}
 case'special':game.specialAction(id,el.dataset.value);render();break;
 case'menu':setModal('menu');break;
 case'begin-order':game.beginOrder();render();break;
 case'finish-order':game.finishOrder();render();break;
 case'shop':setModal(null);break;
 case'new':contract='standard';setModal('new');break;
 case'contract':contract=id;renderModal();break;
 case'start':{const seed=$('#seed')?.value.trim()||'g24-'+Date.now().toString(36);if(s&&s.phase!=='end')game.end(false,'점주가 영업을 마감했습니다.');game.start(seed,contract);selected=null;setModal(null);render();break;}
 case'qty':game.setQuantity(Number(el.dataset.index),Number(el.dataset.q));sound('quantity');render();break;
 case'confirm-order':game.confirmOrder();sound('order');render();break;
 case'night-next':s.nightCursor=Math.min(s.results.length,(s.nightCursor||0)+1);if(s.nightCursor>=s.results.length)game.finishNight();game.save();render();const result=s.results[s.nightCursor];if(result)sound(result.outcome==='사망'?'death':result.outcome==='중상'?'severe':result.outcome==='부상'?'injury':result.outcome==='대성공'?'great':result.discoveries?.length?'discovery':result.changes?.length?'level':'return');break;
 case'relics':setModal('relics');break;
 case'buy-relic':game.buyRelic(id);setModal(null);render();sound('rare');break;
 case'closing':game.finishNight();game.save();render();break;
 case'tip':game.account.tutorial??={};game.account.tutorial[id]=true;game.save();render();break;
 case'open':game.open();selected=null;render();break;
 case'select':selected=id;setModal('saleItem');sound('button');break;
 case'sell':{const success=game.sell(selected,el.dataset.mode);if(success){sound(el.dataset.mode==='overcharge'?'overcharge':el.dataset.mode==='half'?'half':'sale');selected=null;setModal(null);}else{sound('refusal');toast(game.run.notice);}render();break;}
 case'depart':game.depart();selected=null;render();sound(s.phase==='night'?'return':'depart');break;
 case'close':game.closeDay();selected=null;render();if(s.money<0&&s.phase==='closing')setModal('stock');break;
 case'reroll':game.reroll();render();break;
 case'stock':setModal('stock');break;
 case'liquidate':game.liquidate(id);render();break;
 case'roster':setModal('roster');break;
 case'npc':setModal('npc:'+id);break;
 case'codex':setModal('codex');break;
 case'codex-tab':codexTab=id;renderModal();break;
 case'help':setModal('help');break;
 case'settings':setModal('settings');break;
 case'sound':game.account.settings.muted=!game.account.settings.muted;game.save();sound();render();break;
 case'dismiss':if(s?.phase==='foundation')return;setModal(null);break;
 case'team':game.selectFinal(id);supplyNPC=s.team.includes(id)?id:s.team[0];render();break;
 case'supply-target':supplyNPC=id;render();break;
 case'supply':game.supplyFinal(supplyNPC,selected);selected=null;setModal(null);sound();render();break;
 case'boss':setModal('bossConfirm');break;
 case'boss-go':sound('boss');game.boss();setModal(null);render();sound('rare');break;
 case'retire':setModal('retireConfirm');break;
 case'retire-go':game.end(false,'운영비를 충당하지 못해 이번 점포를 마감했습니다.');setModal(null);render();break;
 case'export':{const blob=new Blob([Save.export(game.account,s)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='guild24-save-day-'+(s?.day||0)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다.');break;}
 case'import':setModal('importConfirm');break;
 case'import-go':$('#save-file').click();break;

 }
 const newly=game.account.unlocked.filter(k=>!oldUnlocks.includes(k));if(newly.length){const names=[...D.items,...D.jobs,...D.facilities,...D.contracts].filter(x=>newly.includes(x.unlock)).map(x=>x.name);toast('본사 해금 · '+names.join(' · '));sound('rare');}
 }catch(err){toast(err.message);}
}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el&&!el.disabled)action(el);});
document.addEventListener('keydown',ev=>{if(ev.ctrlKey&&ev.shiftKey&&ev.code==='KeyD'&&game.run){ev.preventDefault();setModal('debug');return;}if(ev.key==='Escape'&&modal&&game.run?.phase!=='foundation'&&(game.run||modal!=='new'))setModal(null);if(ev.key==='Tab'&&modal){const els=[...$('#modal-root').querySelectorAll('button:not(:disabled),input,select,summary,[tabindex="0"]')].filter(e=>e.getClientRects().length),first=els[0],last=els.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
$('#save-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{const save=Save.import(await file.text());game=new Game(save.account,save.run);game.save();selected=null;setModal(null);render();toast('이어서 영업할 준비가 됐습니다.');}catch(e){toast('저장 파일을 읽지 못했습니다. '+e.message);}ev.target.value='';});
window.addEventListener('pagehide',()=>{game.save();Sound.sync(true,game.run?.phase);});document.addEventListener('visibilitychange',()=>{if(document.hidden)game.save();Sound.sync(game.account.settings.muted,game.run?.phase);});
window.Guild24={get game(){return game;},render,simulate:Debug.simulate,showDebug:()=>setModal('debug')};render();
})();
